begin;
create sequence public.quotation_number_seq;
create or replace function public.convert_inquiry(p_inquiry_id uuid,p_project_title text default null) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare i public.inquiries%rowtype; cid uuid; pid uuid; ptitle text; begin if not public.is_admin() then raise exception 'ADMIN_REQUIRED'; end if; select * into i from public.inquiries where id=p_inquiry_id for update; if not found then raise exception 'INQUIRY_NOT_FOUND'; end if; if i.converted_client_id is not null and i.converted_project_id is not null then return jsonb_build_object('client_id',i.converted_client_id,'project_id',i.converted_project_id,'already_converted',true); end if; insert into public.clients(name,email,phone) values(i.full_name,lower(i.email),i.phone) on conflict(email) do update set name=excluded.name returning id into cid; ptitle=coalesce(nullif(trim(p_project_title),''),i.project_type||' — '||i.full_name); insert into public.projects(title,client_id,service_type,location,description,status,created_by) values(ptitle,cid,i.project_type,i.project_location,i.description,'planning',auth.uid()) returning id into pid; update public.inquiries set converted_client_id=cid,converted_project_id=pid,status='converted' where id=i.id; return jsonb_build_object('client_id',cid,'project_id',pid,'already_converted',false); end $$;
revoke all on function public.convert_inquiry(uuid,text) from public,anon;grant execute on function public.convert_inquiry(uuid,text) to authenticated;
create or replace function public.assign_client_user(p_client_id uuid,p_user_id uuid) returns void language plpgsql security definer set search_path=public,auth as $$ declare ce text; pe text; current_role public.app_role; begin if auth.role()<>'service_role' and not public.is_admin() then raise exception 'ADMIN_REQUIRED'; end if; select email into ce from public.clients where id=p_client_id; select email into pe from public.profiles where user_id=p_user_id; if ce is null or pe is null or lower(ce)<>lower(pe) then raise exception 'CLIENT_EMAIL_MISMATCH'; end if; select role into current_role from public.user_roles where user_id=p_user_id; if current_role='admin' then raise exception 'ADMIN_ACCOUNT_CANNOT_BE_ASSIGNED_AS_CLIENT'; end if; insert into public.user_roles(user_id,role) values(p_user_id,'client') on conflict(user_id) do update set role='client',updated_at=now(); insert into public.client_memberships(client_id,user_id) values(p_client_id,p_user_id) on conflict(client_id,user_id) do nothing; insert into public.project_memberships(project_id,user_id) select p.id,p_user_id from public.projects p where p.client_id=p_client_id on conflict do nothing; end $$;
revoke all on function public.assign_client_user(uuid,uuid) from public,anon;grant execute on function public.assign_client_user(uuid,uuid) to authenticated,service_role;
create or replace function public.submit_public_inquiry(p_full_name text,p_email text,p_phone text,p_project_type text,p_project_location text,p_budget_range text,p_desired_start_date date,p_description text,p_privacy_acknowledged boolean,p_idempotency_key uuid,p_rate_key_hash text) returns table(public_reference text) language plpgsql security definer set search_path=public,auth as $$ declare existing_ref text; attempts integer; new_ref text; begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED'; end if; select i.public_reference into existing_ref from public.inquiries i where i.idempotency_key=p_idempotency_key; if existing_ref is not null then return query select existing_ref; return; end if; if p_rate_key_hash is null or length(p_rate_key_hash)<32 then raise exception 'RATE_KEY_REQUIRED'; end if; perform pg_advisory_xact_lock(hashtextextended(p_rate_key_hash,0)); insert into public.submission_rate_limits(rate_key_hash,window_started_at,attempt_count) values(p_rate_key_hash,now(),1) on conflict(rate_key_hash) do update set window_started_at=case when public.submission_rate_limits.window_started_at<now()-interval '1 hour' then now() else public.submission_rate_limits.window_started_at end,attempt_count=case when public.submission_rate_limits.window_started_at<now()-interval '1 hour' then 1 else public.submission_rate_limits.attempt_count+1 end,updated_at=now() returning attempt_count into attempts; if attempts>5 then raise exception 'RATE_LIMITED'; end if; new_ref='FORGE-'||to_char(now(),'YYYY')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)); insert into public.inquiries(public_reference,full_name,email,phone,project_type,project_location,budget_range,desired_start_date,description,privacy_acknowledged,idempotency_key) values(new_ref,trim(p_full_name),lower(trim(p_email)),trim(p_phone),p_project_type,trim(p_project_location),nullif(p_budget_range,''),p_desired_start_date,trim(p_description),p_privacy_acknowledged,p_idempotency_key); return query select new_ref; end $$;
revoke all on function public.submit_public_inquiry(text,text,text,text,text,text,date,text,boolean,uuid,text) from public,anon,authenticated;grant execute on function public.submit_public_inquiry(text,text,text,text,text,text,date,text,boolean,uuid,text) to service_role;
create or replace function public.save_quotation_draft(p_quotation_id uuid,p_quote jsonb,p_items jsonb) returns uuid language plpgsql security definer set search_path=public,auth as $$ declare qid uuid; qno text; rev integer; old public.quotations%rowtype; subtotal numeric(16,2):=0; disc numeric(16,2); rate numeric(7,4); taxable numeric(16,2); tax numeric(16,2); total numeric(16,2); item jsonb; qty numeric(12,3); price numeric(16,2); amount numeric(16,2); begin if not public.is_admin() then raise exception 'ADMIN_REQUIRED'; end if; if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)<1 or jsonb_array_length(p_items)>100 then raise exception 'INVALID_ITEMS'; end if; if p_quotation_id is not null then select * into old from public.quotations where id=p_quotation_id for update; if not found or old.status<>'draft' then raise exception 'ONLY_DRAFTS_CAN_BE_EDITED'; end if; qid=old.id;qno=old.quotation_number;rev=old.revision; else qid=gen_random_uuid(); qno=nullif(trim(p_quote->>'quotation_number'),''); if qno is null then qno='FORGE-Q-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.quotation_number_seq')::text,6,'0'); end if; select coalesce(max(revision),0)+1 into rev from public.quotations where quotation_number=qno; end if; disc=coalesce(nullif(p_quote->>'discount_amount','')::numeric,0);rate=coalesce(nullif(p_quote->>'tax_rate_percent','')::numeric,0);if disc<0 or rate<0 or rate>100 then raise exception 'INVALID_DISCOUNT_OR_TAX'; end if; for item in select * from jsonb_array_elements(p_items) loop if item->>'category' not in ('Materials','Labor','Equipment','Other') then raise exception 'INVALID_ITEM_CATEGORY'; end if; qty=(item->>'quantity')::numeric;price=(item->>'unit_price')::numeric;if qty<=0 or price<0 then raise exception 'INVALID_QUANTITY_OR_PRICE'; end if;amount=round(qty*price,2);subtotal=subtotal+amount;end loop;subtotal=round(subtotal,2);if disc>subtotal then raise exception 'DISCOUNT_EXCEEDS_SUBTOTAL'; end if;if rate>0 and coalesce(trim(p_quote->>'tax_label'),'')='' then raise exception 'TAX_LABEL_REQUIRED'; end if;taxable=subtotal-disc;tax=round(taxable*rate/100,2);total=taxable+tax; if p_quotation_id is null then insert into public.quotations(id,quotation_number,revision,client_id,inquiry_id,project_id,status,currency,valid_until,scope_of_work,terms,notes_visible_to_client,subtotal,discount_amount,tax_label,tax_rate_percent,tax_amount,grand_total,created_by) values(qid,qno,rev,(p_quote->>'client_id')::uuid,nullif(p_quote->>'inquiry_id','')::uuid,nullif(p_quote->>'project_id','')::uuid,'draft','PHP',nullif(p_quote->>'valid_until','')::date,p_quote->>'scope_of_work',coalesce(p_quote->>'terms',''),coalesce(p_quote->>'notes_visible_to_client',''),subtotal,disc,nullif(p_quote->>'tax_label',''),rate,tax,total,auth.uid()); else update public.quotations set valid_until=nullif(p_quote->>'valid_until','')::date,scope_of_work=p_quote->>'scope_of_work',terms=coalesce(p_quote->>'terms',''),notes_visible_to_client=coalesce(p_quote->>'notes_visible_to_client',''),subtotal=subtotal,discount_amount=disc,tax_label=nullif(p_quote->>'tax_label',''),tax_rate_percent=rate,tax_amount=tax,grand_total=total where id=qid; delete from public.quotation_items where quotation_id=qid; end if; for item in select * from jsonb_array_elements(p_items) loop qty=(item->>'quantity')::numeric;price=(item->>'unit_price')::numeric;amount=round(qty*price,2);insert into public.quotation_items(quotation_id,category,description,quantity,unit,unit_price,amount,display_order) values(qid,item->>'category',trim(item->>'description'),qty,trim(item->>'unit'),price,amount,coalesce((item->>'display_order')::integer,0));end loop;return qid;end $$;
revoke all on function public.save_quotation_draft(uuid,jsonb,jsonb) from public,anon;grant execute on function public.save_quotation_draft(uuid,jsonb,jsonb) to authenticated;
create or replace function public.issue_quotation(p_quotation_id uuid) returns text language plpgsql security definer set search_path=public,auth as $$ declare q public.quotations%rowtype; begin if not public.is_admin() then raise exception 'ADMIN_REQUIRED'; end if; select * into q from public.quotations where id=p_quotation_id for update;if not found or q.status<>'draft' then raise exception 'ONLY_DRAFTS_CAN_BE_ISSUED';end if;if q.valid_until is not null and q.valid_until<current_date then raise exception 'VALID_UNTIL_IS_IN_THE_PAST';end if;if not exists(select 1 from public.quotation_items where quotation_id=q.id) then raise exception 'QUOTATION_REQUIRES_ITEMS';end if;perform set_config('app.quote_transition','on',true);update public.quotations set status='superseded' where quotation_number=q.quotation_number and id<>q.id and status='issued';update public.quotations set status='issued',issued_at=now() where id=q.id;return 'issued';end $$;
revoke all on function public.issue_quotation(uuid) from public,anon;grant execute on function public.issue_quotation(uuid) to authenticated;
create or replace function public.respond_to_quotation(p_quotation_id uuid,p_decision text) returns text language plpgsql security definer set search_path=public,auth as $$ declare q public.quotations%rowtype; begin if not public.has_client_role() then raise exception 'CLIENT_REQUIRED';end if;if p_decision not in ('accepted','declined') then raise exception 'INVALID_DECISION';end if;select * into q from public.quotations where id=p_quotation_id for update;if not found or not exists(select 1 from public.client_memberships cm where cm.client_id=q.client_id and cm.user_id=auth.uid()) then raise exception 'QUOTATION_NOT_FOUND';end if;if q.status=p_decision and q.response_by=auth.uid() then return q.status::text;end if;if q.status<>'issued' then raise exception 'QUOTATION_NOT_ELIGIBLE';end if;if q.valid_until is not null and q.valid_until<current_date then perform set_config('app.quote_transition','on',true);update public.quotations set status='expired' where id=q.id;return 'expired';end if;perform set_config('app.quote_transition','on',true);update public.quotations set status=p_decision::public.quotation_status,response_by=auth.uid(),responded_at=now() where id=q.id;return p_decision;end $$;
revoke all on function public.respond_to_quotation(uuid,text) from public,anon;grant execute on function public.respond_to_quotation(uuid,text) to authenticated;
create or replace function public.guard_quotation_update() returns trigger language plpgsql set search_path=public as $$ begin if current_setting('app.quote_transition',true)='on' then return new; end if; if new.status<>old.status then raise exception 'USE_SERVER_QUOTATION_TRANSITION'; end if; if old.status<>'draft' and (new.quotation_number,new.revision,new.client_id,new.inquiry_id,new.project_id,new.currency,new.issued_at,new.valid_until,new.scope_of_work,new.terms,new.notes_visible_to_client,new.subtotal,new.discount_amount,new.tax_label,new.tax_rate_percent,new.tax_amount,new.grand_total,new.response_by,new.responded_at) is distinct from (old.quotation_number,old.revision,old.client_id,old.inquiry_id,old.project_id,old.currency,old.issued_at,old.valid_until,old.scope_of_work,old.terms,old.notes_visible_to_client,old.subtotal,old.discount_amount,old.tax_label,old.tax_rate_percent,old.tax_amount,old.grand_total,old.response_by,old.responded_at) then raise exception 'ISSUED_QUOTATION_IS_IMMUTABLE'; end if; return new;end $$;
create trigger quotations_immutable before update on public.quotations for each row execute function public.guard_quotation_update();
create or replace function public.guard_quotation_item_edit() returns trigger language plpgsql set search_path=public as $$ declare qid uuid; st public.quotation_status; begin qid=coalesce(new.quotation_id,old.quotation_id);select status into st from public.quotations where id=qid;if st<>'draft' then raise exception 'ISSUED_QUOTATION_ITEMS_ARE_IMMUTABLE';end if;return coalesce(new,old);end $$;
create trigger quotation_items_draft_only before insert or update or delete on public.quotation_items for each row execute function public.guard_quotation_item_edit();
-- Assign a client to projects atomically when membership is added.
create or replace function public.sync_client_projects() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.project_memberships(project_id,user_id) select p.id,new.user_id from public.projects p where p.client_id=new.client_id on conflict do nothing; return new;end $$;
create trigger client_membership_sync after insert on public.client_memberships for each row execute function public.sync_client_projects();
-- Private storage buckets. Published portfolio assets are readable only through storage RLS and short-lived signed URLs.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('portfolio-assets','portfolio-assets',false,10485760,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=array['image/jpeg','image/png','image/webp','image/avif'];
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-private','project-private',false,20971520,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=20971520,allowed_mime_types=array['image/jpeg','image/png','image/webp','application/pdf'];
create or replace function public.safe_project_uuid(path text) returns uuid language plpgsql immutable as $$ begin return split_part(path,'/',1)::uuid; exception when others then return null; end $$;
create policy portfolio_storage_admin_all on storage.objects for all to authenticated using(bucket_id='portfolio-assets' and public.is_admin()) with check(bucket_id='portfolio-assets' and public.is_admin());
create policy portfolio_storage_published_read on storage.objects for select to anon,authenticated using(bucket_id='portfolio-assets' and exists(select 1 from public.portfolio_images pi join public.portfolio_entries pe on pe.id=pi.portfolio_entry_id where pi.storage_path=name and pi.bucket_id=bucket_id and pe.is_published and pe.archived_at is null));
create policy project_storage_admin_all on storage.objects for all to authenticated using(bucket_id='project-private' and public.is_admin()) with check(bucket_id='project-private' and public.is_admin());
create policy project_storage_member_read on storage.objects for select to authenticated using(bucket_id='project-private' and (exists(select 1 from public.project_photos p where p.storage_path=name and p.bucket_id=bucket_id and p.is_client_visible and public.is_project_member(p.project_id)) or exists(select 1 from public.project_documents d where d.storage_path=name and d.bucket_id=bucket_id and d.is_client_visible and public.is_project_member(d.project_id))));
-- Server-only anonymous submission RPC: the application hashes the network key with a private pepper.
commit;
